-- 队列基础：循环数组用模运算复用队头之前的槽位。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '循环队列的数组表示','front 与 rear 通过模运算在数组中回绕，避免顺序队列的假溢出。',course.id,parent.id,'cs408-circular-queue-representation','AISTU',1,'REVIEWED',9,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-circular-queue-representation' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-circular-queue-representation',1,'REVIEWED','循环队列的数组表示',JSON_OBJECT('summary','容量为 m 的循环队列用 front 指示队头，rear 可指示下一入队位置或队尾，具体语义必须统一。逻辑位置通过模 m 映射到物理槽位；入队和出队分别用 rear=(rear+1) mod m、front=(front+1) mod m 回绕。','steps',JSON_ARRAY('数组下标首尾相接形成逻辑环','front 标识当前队头位置','rear 的含义必须在实现内保持统一','入队和出队下标都通过模 m 回绕','回绕后可复用队头之前已经释放的槽位'),'visualization',JSON_OBJECT('kind','ARRAY_QUEUE_REPRESENTATION','version',1,'capacity',6,'headIndex',4,'elements',JSON_ARRAY('A','B','C')),'prerequisite',JSON_OBJECT('contentKey','cs408-queue-fifo','title','队列的 FIFO 语义与基本操作','description','先掌握队头删除、队尾插入的逻辑顺序。'),'nextStep',JSON_OBJECT('contentKey','cs408-circular-queue-state','title','循环队列判空、判满与长度','description','继续区分 front=rear 所代表的状态。')),JSON_OBJECT('id','circular-queue-representation-v1','prompt','循环队列为何能复用数组前部已经释放的槽位？','options',JSON_ARRAY(JSON_OBJECT('id','MODULO_WRAP','text','front 和 rear 通过模 m 运算回绕'),JSON_OBJECT('id','SHIFT_ALL','text','每次出队都把所有元素左移')),'correctOptionId','MODULO_WRAP','correctExplanation','正确：模运算让物理下标越过末端后回到 0，无需整体搬移。','incorrectExplanation','不正确：循环队列的目标正是避免每次出队后的整体搬移。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-circular-queue-representation' AND existing.content_version=1 WHERE point.content_key='cs408-circular-queue-representation' AND existing.id IS NULL;
